    {"원어": "πληθύνω (플레뒤노)", "의미_문법": "더하여지다, 풍성해지다 - 동사 수동태 기원법. 기하급수적으로 증가하다", "설교포인트": "은혜와 평강이 단순히 더해지는 것이 아니라 넘치도록 풍성해지기를 기원한다. 하나님을 알아가는 것은 은혜와 평강의 곱셈을 가져온다"}
