    {"새찬송가": "288", "통일찬송가": "305", "제목": "나의 죄를 씻기는", "선정이유": "세상의 부패와 정욕에서 씻겨 거룩하게 되는 것을 노래한다"},
    {"새찬송가": "393", "통일찬송가": "446", "제목": "내가 매일 기쁘게", "선정이유": "하나님의 성품을 닮아 매일 거룩한 삶을 사는 기쁨을 표현한다"}
