    {"새찬송가": "406", "통일찬송가": "459", "제목": "큰 죄에 빠진 날 위해", "선정이유": "죄의 유혹에서 절제하며 주님의 은혜를 의지하는 삶을 노래한다"},
    {"새찬송가": "449", "통일찬송가": "354", "제목": "눈을 들어 하늘 보라", "선정이유": "인내 가운데 하나님을 향한 경건한 시선을 유지하는 것을 표현한다"}
