    {"항목": "베드로의 순교 예감", "내용": "베드로는 주후 64-67년경 네로의 박해 때 순교한 것으로 전해진다. 전승에 따르면 그는 자신이 주님처럼 십자가에 달릴 자격이 없다 하여 거꾸로 십자가에 못 박혔다고 한다", "목회적활용": "죽음 앞에서도 진리를 전하는 것을 최우선 사명으로 여긴 베드로의 자세는 모든 사역자의 모범이다"}
