    {"구분": "엘리야의 마지막 사역", "내용": "엘리야는 하늘로 올리움을 받기 전 마지막까지 엘리사를 가르치고 사역했다(왕하 2장). 마지막 순간까지 다음 세대를 세우는 것이 사명이었다", "그리스도연결": "그리스도께서도 승천 전 마지막까지 제자들을 가르치시고 위임하셨다(행 1:3-8). 베드로도 순교 전 마지막까지 성도를 일깨운다"}
