    {"대지": "서론", "내용": "베드로는 놀라운 변화산 체험 후에도 예언의 말씀이 더 확실하다고 선언한다. 체험은 사라지지만 말씀은 영원하기 때문이다", "예화_적용": "불꽃놀이는 순간적으로 아름답지만 등대의 빛은 밤새 항구를 비춘다. 체험은 불꽃놀이요 말씀은 등대이다"},
    {"대지": "1대지: 더 확실한 예언 (권위)", "내용": "기록된 예언은 개인적 체험보다 더 확실한 기초이다. 체험은 주관적이지만 말씀은 객관적이며 변하지 않는다", "예화_적용": "계약서가 구두 약속보다 법적으로 강력하듯 기록된 말씀이 개인적 체험보다 더 확고한 증거이다"},
    {"대지": "2대지: 어두운 데 비치는 등불 (인도)", "내용": "이 세상은 영적으로 어두운 곳이다. 이 어둠 속에서 예언의 말씀만이 길을 비추는 등불이다", "예화_적용": "칠흑 같은 어둠에서 작은 손전등 하나가 생명을 구할 수 있듯 영적 어둠에서 말씀 한 절이 영혼을 구한다"},
    {"대지": "3대지: 샛별이 떠오르기까지 (소망)", "내용": "샛별은 그리스도의 재림이다. 재림의 아침이 밝아올 때까지 예언의 등불을 주의하며 걸어가야 한다", "예화_적용": "밤길을 걷는 나그네에게 동쪽 하늘의 샛별은 곧 아침이 온다는 희망이다. 그리스도의 재림은 영원한 아침의 약속이다"},
    {"대지": "결론", "내용": "말씀이라는 등불을 들고 어둠 속을 걸어가자. 그리고 샛별이 마음에 떠오르는 그 날, 영원한 아침을 맞이하자", "예화_적용": "밤이 깊을수록 새벽은 가깝다. 이 세상의 어둠이 깊을수록 그리스도의 재림은 가까이 있다"}
