    {"상황": "미래에 대한 불안으로 힘들어하는 성도", "성경원리": "예언의 말씀은 어두운 데 비치는 등불이다. 미래가 불확실해 보여도 하나님의 말씀이 길을 비추며 재림의 샛별이 영원한 아침을 가져올 것이다", "실제적용": "불안의 감정을 인정하면서도 말씀의 약속에 시선을 고정하도록 도우라. 구체적인 약속의 말씀을 묵상하며 소망을 회복하도록 안내하라"}
