    {"대지": "서론", "내용": "베드로는 예언이 더 확실하다고 선언한 후 그 예언을 어떻게 대해야 하는지를 가르친다. 먼저 알 것은 사사로이 풀지 말라는 것이다", "예화_적용": "좋은 약도 용법을 지켜야 효과가 있듯 좋은 말씀도 바른 해석의 원칙을 따라야 유익하다"},
    {"대지": "1대지: 먼저 알 것 (우선순위)", "내용": "이것을 먼저 알라는 것은 성경 해석의 원칙이 다른 모든 것에 앞서야 한다는 뜻이다. 해석 원칙이 잘못되면 모든 것이 잘못된다", "예화_적용": "건물의 기초가 틀어지면 건물 전체가 기울어지듯 해석의 기초가 잘못되면 신앙 전체가 왜곡된다"},
    {"대지": "2대지: 사사로이 풀지 말라 (겸손)", "내용": "이디오스는 자기만의 것이라는 뜻이다. 성경을 자기 뜻대로 해석하는 것은 하나님의 말씀을 자기 것으로 만드는 교만이다", "예화_적용": "남의 편지를 받아서 자기 뜻대로 해석하면 그것은 편지 쓴 사람의 의도를 무시하는 것이다. 성경은 하나님이 쓰신 편지이다"},
    {"대지": "3대지: 공적 해석의 원칙 (공동체)", "내용": "성경은 교회 공동체에 주어진 것이며 성령의 인도와 교회의 전통 안에서 해석되어야 한다. 개인의 독단은 이단의 시작이다", "예화_적용": "악보를 혼자 마음대로 연주하면 불협화음이 나지만 지휘자의 인도 아래 합주하면 아름다운 음악이 된다. 성경도 성령이라는 지휘자 아래 읽어야 한다"},
    {"대지": "결론", "내용": "성경을 읽을 때 겸손한 자세로 성령의 조명을 구하고 교회 공동체의 지혜를 참고하자. 사사로운 해석은 진리를 왜곡한다", "예화_적용": "지도를 거꾸로 보면 목적지에 도달할 수 없다. 바른 해석의 원칙으로 성경이라는 지도를 바르게 읽어야 한다"}
