    {"새찬송가": "345", "통일찬송가": "495", "제목": "주 날개 밑 내가 편히 쉬네", "선정이유": "심판의 두려움 속에서도 주님의 보호 안에 안전함을 고백한다"},
    {"새찬송가": "251", "통일찬송가": "260", "제목": "주 예수여 은혜와", "선정이유": "심판 앞에서 오직 주님의 은혜만이 소망임을 노래한다"}
