    {"항목": "일곱 식구의 보존", "내용": "노아와 그의 아내, 세 아들(셈, 함, 야벳)과 세 며느리, 총 여덟 명이 방주에 들어가 구원받았다. 전 인류 중 여덟 명만 구원받은 것은 심판의 엄중함과 동시에 은혜의 확실성을 보여준다", "목회적활용": "하나님은 의로운 자를 심판 가운데서도 반드시 구원하신다. 이것이 9절의 결론으로 이어진다"}
