    {"영어원문": "Noah, a preacher of righteousness — he preached by his words and by his works; building the ark was itself a sermon against sin and for faith.", "한국어번역": "의를 전파하는 노아 — 그는 말과 행위로 전파했다. 방주를 짓는 것 자체가 죄에 대한 그리고 믿음을 위한 설교였다.", "핵심통찰": "노아의 방주 건축은 말없는 설교였다. 삶이 곧 메시지이다"}
