    {"항목": "후세에 경고적 본보기", "내용": "베드로는 소돔의 멸망이 단순한 역사적 사건이 아니라 후세를 위한 경고적 본보기임을 강조한다. 유다서 7절도 같은 관점을 취한다. 소돔의 심판은 모든 시대의 불경건한 자들에게 경고이다", "목회적활용": "역사적 심판 사건을 단순한 이야기가 아닌 현재와 미래를 위한 경고로 가르쳐야 한다"}
