    {"원어": "βλάσφημος (블라스페모스)", "의미_문법": "모독하는, 훼방하는 - 형용사, 여성 단수 대격", "설교포인트": "천사들은 훼방하는 판결을 내리지 않았습니다. 반면 거짓 교사들은 천사보다 약하면서도 함부로 훼방했습니다. 이 대조는 그들의 무모함이 얼마나 심각한지를 보여줍니다"}
