    {"원어": "ἄλογος (알로고스)", "의미_문법": "이성 없는, 비합리적인 - 형용사, 중성 복수 주격", "설교포인트": "거짓 교사들이 이성 없는 짐승에 비유되었습니다. 하나님이 주신 이성과 분별력을 사용하지 않고 본능에만 따라 사는 것은 짐승과 다를 바 없습니다"},
    {"원어": "ζῷον (조온)", "의미_문법": "동물, 생물 - 중성 복수 주격", "설교포인트": "짐승은 본능으로 살며 도덕적 분별이 없습니다. 거짓 교사들이 짐승에 비유된 것은 그들이 도덕적 분별력을 완전히 상실했음을 의미합니다"},
    {"원어": "φθορά (프도라)", "의미_문법": "부패, 멸망, 파괴 - 여성 단수 여격", "설교포인트": "멸망은 자연스러운 결과입니다. 짐승이 잡혀 죽듯이 거짓 교사들도 자신의 행위의 결과로 멸망합니다. 죄의 삯은 사망입니다(롬 6:23)"},
    {"원어": "ἁλίσκομαι (할리스코마이)", "의미_문법": "잡히다, 포획되다 - 현재 수동 부정사", "설교포인트": "짐승이 잡혀 죽기 위해 태어난 것처럼 거짓 교사들도 자기 행위로 인해 멸망의 그물에 잡힙니다. 죄의 그물은 처음에는 보이지 않지만 점점 조여옵니다"},
    {"원어": "ἀγνοέω (아그노에오)", "의미_문법": "알지 못하다, 무지하다 - 현재 능동 분사", "설교포인트": "알지 못하면서 훼방하는 것은 이중의 죄입니다. 무지와 교만이 결합하면 가장 위험한 상태가 됩니다. 참된 지혜의 시작은 자기의 무지를 인정하는 것입니다"}
