    {"교리": "죄의 자동적 결과로서의 심판", "설명": "짐승이 잡혀 죽는 것이 자연의 법칙이듯 거짓 교사들의 멸망도 죄의 필연적 결과이다. 하나님의 심판은 외부에서 자의적으로 부과되는 것이 아니라 죄 자체에 내재된 파괴력의 발현이다", "관련구절": "갈 6:7-8, 롬 6:23, 잠 11:19"}
