    {"대지": "3대지: 공동체의 오염 - 점과 흠이 되다(스필로스, 모모스)", "내용": "거짓 교사들은 교회의 교제 자리를 속임과 쾌락의 도구로 악용했다. 깨끗한 옷에 얼룩이 묻으면 전체가 더러워지듯 교회 공동체도 거짓 교사로 인해 전체가 오염될 수 있다", "예화_적용": "적용: 교회의 교제가 서로를 세우는 거룩한 시간이 되도록 힘쓰라. 교제의 자리를 개인적 이익이나 쾌락을 위해 이용하지 말라"},
    {"대지": "결론", "내용": "교회의 순결을 지키는 것은 모든 성도의 책임이다. 거짓 가르침과 부도덕한 행위를 분별하고 교회의 교제가 참된 사랑과 진리 위에 세워지도록 힘쓰자", "예화_적용": "결단: 교회 공동체의 순결을 위해 기도하고 자신부터 점과 흠 없는 삶을 추구하자(벧후 3:14)"}
