    {"구절": "딤전 4:2", "연결점": "자기 양심이 화인 맞아서 외식함으로 거짓말하는 자들이라", "구분": "신약"},
    {"구절": "잠 22:8", "연결점": "악을 뿌리는 자는 재앙을 거두리니 그 분노의 기세가 쇠하리라", "구분": "구약"}
